          "snippet": "Value quantiles p50 83.93, p95 237.22, p99 331.91; mean of key means 100.014 (p99/p50 = 3.96x; mean exceeds median, right-skewed tail)"
        },
        {
          "title": "bench_execute — hourly load profile",
          "url": "local://working-dataset/L/hourly",
          "snippet": "Peak hour 21 — highest hourly load across the one-week window, the anchor for capacity planning and failover scheduling"
        },
        {
          "title": "bench_execute — anomaly detection over merchant keys",
          "url": "local://working-dataset/L/anomalies",
          "snippet": "Outliers 13; max high-value share 0.0583 (5.83% of events for the most high-value-heavy merchant)"
        },
        {
          "title": "bench_record — retrieved analysis context (record 'Research the topic: Using ONLY the datas')",
          "url": "local://records/Research-the-topic-Using-ONLY-the-datas",
          "snippet": "Context emphasizes tool-path weighing, monitoring segments, revenue decision, memory/bandwidth reporting, routing teams, burst service, failover scheduling, and pipeline predictability recommendations"
        }
      ]
    }
  }
}

