      "description": "Tool-work-based capacity estimator for an orchestration host: forecasts cost per workflow from tool-call concurrency against known contention thresholds (from field records), instead of from model token counts.",
      "code": "# Known contention thresholds and shard remedies observed in ops records\nPOOLS = {\n    \"attention\":  {\"cliff\": 3964, \"shards\": 22},   # chunk-26122\n    \"softmax\":    {\"cliff\": 3862, \"shards\": 75},   # chunk-26119\n    \"queue\":      {\"cliff\": 2916, \"shards\": 88},   # chunk-26136\n    \"replica\":    {\"cliff\": 3652, \"shards\": 18},   # chunk-26138\n    \"ceiling\":    {\"cliff\": 3570, \"shards\": 40},   # chunk-26125\n}\nUTIL_CEILING = 0.68  # healthy eval ran <68% utilization (chunk-26136)\n\ndef plan_host(workflows_per_hr, tool_calls_per_wf, avg_tool_secs):\n    tool_secs_per_hr = workflows_per_hr * tool_calls_per_wf * avg_tool_secs\n    peak_concurrency = tool_secs_per_hr / 3600 * 1.5  # burst factor\n    hosts = {}\n    for pool, spec in POOLS.items():\n        safe_load = spec[\"cliff\"] * UTIL_CEILING\n        n_shards = max(spec[\"shards\"], int(peak_concurrency / safe_load) + 1)\n        hosts[pool] = n_shards\n    cost_per_workflow = tool_calls_per_wf * avg_tool_secs  # tool work, NOT tokens\n    return {\"shards\": hosts, \"cost_model\": f\"{cost_per_workflow:.1f} tool-secs/workflow\"}\n\nprint(plan_host(workflows_per_hr=500, tool_calls_per_wf=24, avg_tool_secs=6))"
    }
  ],
