    {
      "language": "python",
      "description": "Cost-per-workflow estimator keyed to tool work (pool hold-times), not model compute, with threshold alerts derived from the field records",
      "code": "# Thresholds from topic435 operations records\nALERTS = {\n    \"saturation_units\":  {\"warn\": 2182},   # memory latency degrades [chunk-26108]\n    \"replica_units\":     {\"warn\": 2390},   # kernel deadline degrades [chunk-26138]\n    \"sampling_units\":    {\"crit\": 4043},   # variance embedding degrades [chunk-26111]\n    \"backlog_units\":     {\"crit\": 4133},   # cache memory degrades [chunk-26122]\n}\n# Planned sharding factors (largest proven remediations)\nSHARD_PLAN = {\"queue\": 88, \"backlog\": 86, \"shard\": 84, \"pipeline\": 78}  # [chunk-26136,26100,26108,26128]\n\ndef cost_per_workflow(tool_execs, avg_hold_ms, pool_count):\n    \"\"\"Host cost driven by tool work: execs x hold-time / parallel pools.\"\"\"\n    shards = sum(SHARD_PLAN.get(p, 1) for p in pool_count)\n    return (tool_execs * avg_hold_ms) / max(shards, 1)\n\ndef check_load(metrics):\n    flags = []\n    for res, th in ALERTS.items():\n        v = metrics.get(res, 0)\n        if \"crit\" in th and v >= th[\"crit\"]: flags.append(f\"CRIT {res}={v}\")\n        elif \"warn\" in th and v >= th[\"warn\"]: flags.append(f\"WARN {res}={v}\")\n    return flags\n"
    }
  ],
